def createparser():
    """Create the argument parser for the pysemver CLI."""
    import argparse
    parser = argparse.ArgumentParser(
        prog='pysemver',
        description='Semver command-line tool',
    )
    subparsers = parser.add_subparsers(dest='command')

    # bump command
    bump_parser = subparsers.add_parser('bump', help='Bump a version component')
    bump_parser.add_argument('version', help='Version string')
    bump_group = bump_parser.add_mutually_exclusive_group(required=True)
    bump_group.add_argument('--major', action='store_true', help='Bump major')
    bump_group.add_argument('--minor', action='store_true', help='Bump minor')
    bump_group.add_argument('--patch', action='store_true', help='Bump patch')
    bump_group.add_argument('--prerelease', action='store_true', help='Bump prerelease')
    bump_group.add_argument('--build', action='store_true', help='Bump build')

    # replace command
    replace_parser = subparsers.add_parser('replace', help='Replace version components')
    replace_parser.add_argument('version', help='Version string')
    replace_parser.add_argument('--major', type=int, help='New major version')
    replace_parser.add_argument('--minor', type=int, help='New minor version')
    replace_parser.add_argument('--patch', type=int, help='New patch version')
    replace_parser.add_argument('--prerelease', help='New prerelease tag')
    replace_parser.add_argument('--build', help='New build metadata')

    return parser


def process(args):
    """Process CLI arguments and return the result as a string."""
    if args.command == 'bump':
        vi = parse_version_info(args.version)
        if args.major:
            result = vi.bump_major()
        elif args.minor:
            result = vi.bump_minor()
        elif args.patch:
            result = vi.bump_patch()
        elif args.prerelease:
            result = vi.bump_prerelease()
        elif args.build:
            result = vi.bump_build()
        else:
            raise ValueError("No bump option specified")
        return str(result)
    elif args.command == 'replace':
        kwargs = {}
        if args.major is not None:
            kwargs['major'] = args.major
        if args.minor is not None:
            kwargs['minor'] = args.minor
        if args.patch is not None:
            kwargs['patch'] = args.patch
        if args.prerelease is not None:
            kwargs['prerelease'] = args.prerelease
        if args.build is not None:
            kwargs['build'] = args.build
        return replace(args.version, **kwargs)
    else:
        raise ValueError("No command specified")


def main(argv=None):
    """Main entry point for the pysemver CLI."""
    parser = createparser()
    args = parser.parse_args(argv)
    try:
        result = process(args)
        print(result)
    except Exception as e:
        print(f"Error: {e}", file=__import__('sys').stderr)
        return 1
    return 0


